-- Class feature definitions.
-- Compact JSON data is expanded by SQLite JSON1; descriptions are concise mechanical summaries.
WITH desired AS (
  SELECT
    json_extract(value,'$[0]') AS slug,
    json_extract(value,'$[1]') AS name,
    json_extract(value,'$[2]') AS source_page,
    json_extract(value,'$[3]') AS description,
    json_extract(value,'$[4]') AS choice_kind
  FROM json_each('[["barbarian-weapon-armor-proficiency","Weapon and Armor Proficiency","25","Proficient with all simple and martial weapons, light and medium armor, and shields except tower shields.",null],["barbarian-fast-movement","Fast Movement","25","Land speed increases by 10 feet while in no, light, or medium armor and not carrying a heavy load.",null],["barbarian-illiteracy","Illiteracy","25","Does not automatically read and write; literacy can be purchased with skill points or gained by taking another class.",null],["barbarian-rage","Rage","25-26","Enter a battle rage a limited number of times per day, gaining Strength, Constitution, and Will benefits with an Armor Class penalty.",null],["barbarian-uncanny-dodge","Uncanny Dodge","26","Retain Dexterity bonus to Armor Class when flat-footed or attacked by an unseen foe, subject to the class feature''s restrictions.",null],["barbarian-trap-sense","Trap Sense","26","Gain a scaling bonus on Reflex saves and Armor Class against traps.",null],["barbarian-improved-uncanny-dodge","Improved Uncanny Dodge","26","Cannot be flanked except by a sufficiently higher-level rogue; compatible uncanny-dodge class levels stack as described.",null],["barbarian-damage-reduction","Damage Reduction","26","Reduce damage from weapons and natural attacks by a scaling amount.",null],["barbarian-greater-rage","Greater Rage","26","Improves the ability-score and Will bonuses granted by rage.",null],["barbarian-indomitable-will","Indomitable Will","26","While raging, gain an additional bonus on Will saves against enchantment spells.",null],["barbarian-tireless-rage","Tireless Rage","26","No longer become fatigued when a rage ends.",null],["barbarian-mighty-rage","Mighty Rage","26","Further improves the Strength, Constitution, and Will bonuses granted by rage.",null],["bard-weapon-armor-proficiency","Weapon and Armor Proficiency","28","Proficient with simple weapons plus longsword, rapier, sap, short sword, shortbow, and whip; proficient with light armor and shields except tower shields.",null],["bard-spells","Spells","28","Casts arcane bard spells spontaneously using Charisma; bard spells have verbal components and spells known are limited by class level.",null],["bard-bardic-knowledge","Bardic Knowledge","28","Make a special lore check using bard level plus Intelligence modifier for notable people, items, and places.",null],["bard-bardic-music","Bardic Music","29","Use bardic music or poetics once per day per bard level; individual effects have level and Perform-rank requirements.",null],["bard-countersong","Countersong","29","Use a Perform check to counter qualifying sonic or language-dependent magical effects.",null],["bard-fascinate","Fascinate","29","Use bardic music to fascinate creatures that can see, hear, and attend to the bard.",null],["bard-inspire-courage","Inspire Courage","29","Grant allies a scaling morale bonus against charm and fear and on attack and weapon damage rolls.",null],["bard-inspire-competence","Inspire Competence","29","Grant an ally a competence bonus on an appropriate skill check while the bard performs.",null],["bard-suggestion","Suggestion","29","Make a suggestion to a creature already fascinated by the bard.",null],["bard-inspire-greatness","Inspire Greatness","29","Grant temporary combat benefits and bonus Hit Dice to one or more willing allies.",null],["bard-song-of-freedom","Song of Freedom","29","Produce an effect equivalent to break enchantment on a single target after sustained performance.",null],["bard-inspire-heroics","Inspire Heroics","29-30","Grant strong morale saving-throw and dodge Armor Class bonuses to willing allies.",null],["bard-mass-suggestion","Mass Suggestion","30","Apply suggestion simultaneously to multiple creatures already fascinated by the bard.",null],["cleric-weapon-armor-proficiency","Weapon and Armor Proficiency","31","Proficient with all simple weapons, all armor, and shields except tower shields; War-domain weapon training is handled by domain rules.",null],["cleric-spells","Spells","32","Prepares and casts divine cleric spells using Wisdom; gains one domain spell slot at each accessible spell level from 1st through 9th.",null],["cleric-aura","Aura","32","A cleric of a chaotic, evil, good, or lawful deity has a correspondingly powerful alignment aura.",null],["cleric-turn-rebuke-undead","Turn or Rebuke Undead","33","A cleric channels divine energy to turn or rebuke undead according to alignment and deity.",null],["cleric-domains","Domains","32","Choose two domains associated with the deity or cause, gaining their granted powers and access to domain spells.",null],["cleric-spontaneous-casting","Spontaneous Casting","32","May convert prepared non-domain spells into cure spells if good-aligned, or inflict spells if evil-aligned; neutral clerics choose according to deity/campaign rules.",null],["druid-weapon-armor-proficiency","Weapon and Armor Proficiency","34","Proficient with the listed druid weapons, light and medium nonmetal armor, and nonmetal shields except tower shields; natural attacks of wild-shape forms are usable.",null],["druid-spells","Spells","34-35","Prepares and casts divine druid spells using Wisdom.",null],["druid-spontaneous-casting","Spontaneous Casting","35","May lose a prepared spell to cast a summon nature''s ally spell of the same or lower level.",null],["druid-animal-companion","Animal Companion","35","Begin play with an animal companion whose abilities improve with druid level.",null],["druid-nature-sense","Nature Sense","35","Gain a bonus on Knowledge (nature) and Survival checks.",null],["druid-wild-empathy","Wild Empathy","35","Influence animals with a check based on druid level and Charisma modifier.",null],["druid-woodland-stride","Woodland Stride","36","Move through natural undergrowth at normal speed without taking the usual impairment.",null],["druid-trackless-step","Trackless Step","36","Leave no trail in natural surroundings unless choosing to do so.",null],["druid-resist-natures-lure","Resist Nature''s Lure","36","Gain a saving-throw bonus against spell-like abilities of fey.",null],["druid-wild-shape","Wild Shape","36-37","Assume animal forms, later expanding uses, sizes, and form categories with druid level.",null],["druid-venom-immunity","Venom Immunity","37","Gain immunity to poisons.",null],["druid-a-thousand-faces","A Thousand Faces","37","Alter appearance at will while in normal form as described by the class feature.",null],["druid-timeless-body","Timeless Body","37","No longer take ability-score penalties for aging, while bonuses and lifespan continue normally.",null],["fighter-weapon-armor-proficiency","Weapon and Armor Proficiency","38","Proficient with all simple and martial weapons, all armor, and all shields including tower shields.",null],["fighter-bonus-feat","Fighter Bonus Feat","38","Gain a combat-oriented bonus feat from the fighter bonus-feat list, meeting all prerequisites.","feat"],["monk-weapon-armor-proficiency","Weapon and Armor Proficiency","40","Proficient with the monk weapon list; not proficient with armor or shields, and several monk abilities require being unarmored and unencumbered.",null],["monk-ac-bonus","AC Bonus","40","While unarmored and unencumbered, add Wisdom bonus to Armor Class and gain a scaling class Armor Class bonus.",null],["monk-flurry-of-blows","Flurry of Blows","40-41","Make an extra attack in a full attack with unarmed strikes or special monk weapons, with penalties that improve by level.",null],["monk-unarmed-strike","Unarmed Strike","41","Gain Improved Unarmed Strike and scaling unarmed damage; attacks may use fists or other body parts as described.",null],["monk-bonus-feat","Monk Bonus Feat","41","Choose from the level-appropriate monk bonus-feat options without needing the normal prerequisites described for those choices.","feat"],["monk-evasion","Evasion","41","On a successful Reflex save against an effect that normally deals half damage, take no damage when eligible.",null],["monk-still-mind","Still Mind","41","Gain a saving-throw bonus against enchantment spells and effects.",null],["monk-ki-strike","Ki Strike","41","Unarmed attacks gain scaling properties for overcoming damage reduction.",null],["monk-slow-fall","Slow Fall","41","Reduce falling danger when near a wall, with maximum distance improving by level and eventually becoming unlimited.",null],["monk-purity-of-body","Purity of Body","41","Gain immunity to diseases except supernatural and magical diseases as specified.",null],["monk-wholeness-of-body","Wholeness of Body","42","Heal personal hit point damage each day based on monk level.",null],["monk-improved-evasion","Improved Evasion","42","Evasion improves so failed qualifying Reflex saves deal only half damage while successful saves deal none.",null],["monk-greater-flurry","Greater Flurry","42","Flurry of blows grants an additional extra attack at the highest attack bonus.",null],["monk-diamond-body","Diamond Body","42","Gain immunity to poisons.",null],["monk-abundant-step","Abundant Step","42","Use dimension door as a supernatural ability once per day at the class-defined caster level.",null],["monk-diamond-soul","Diamond Soul","42","Gain spell resistance based on monk level.",null],["monk-quivering-palm","Quivering Palm","42","Set up a lethal vibration in a qualifying creature on a limited schedule, subject to the class feature''s save and target restrictions.",null],["monk-timeless-body","Timeless Body","42","No longer take ability-score penalties for aging, while bonuses and lifespan continue normally.",null],["monk-tongue-sun-moon","Tongue of the Sun and Moon","42","Speak with any living creature.",null],["monk-empty-body","Empty Body","42","Become ethereal for a limited number of rounds per day.",null],["monk-perfect-self","Perfect Self","42","Become a magical creature with the outsider type and gain the class feature''s damage reduction and related effects.",null],["monk-unarmored-speed-bonus","Unarmored Speed Bonus","40","Gain a scaling enhancement to land speed while meeting monk armor and load restrictions.",null],["paladin-weapon-armor-proficiency","Weapon and Armor Proficiency","44","Proficient with all simple and martial weapons, all armor, and shields except tower shields.",null],["paladin-aura-of-good","Aura of Good","44","Project an aura of good whose power is based on paladin level.",null],["paladin-detect-evil","Detect Evil","44","Use detect evil at will as a spell-like ability.",null],["paladin-smite-evil","Smite Evil","44","Add Charisma to an attack and paladin level to damage against an evil target a limited number of times per day.",null],["paladin-divine-grace","Divine Grace","44","Add Charisma bonus to all saving throws.",null],["paladin-lay-on-hands","Lay on Hands","44","Heal wounds each day from a pool based on Charisma bonus and paladin level; may damage undead instead.",null],["paladin-aura-of-courage","Aura of Courage","44","Become immune to fear and grant nearby allies a morale bonus on saves against fear.",null],["paladin-divine-health","Divine Health","44","Gain immunity to diseases including supernatural and magical diseases.",null],["paladin-turn-undead","Turn Undead","44","Turn undead as a cleric of three levels lower, subject to the class feature''s uses.",null],["paladin-spells","Spells","44","Beginning at 4th level, prepare and cast divine paladin spells using Wisdom; caster level is one-half paladin level.",null],["paladin-special-mount","Special Mount","45","Call an unusually intelligent and strong mount that improves with paladin level.",null],["paladin-remove-disease","Remove Disease","45","Use remove disease a limited number of times per week, increasing with level.",null],["paladin-code-of-conduct","Code of Conduct","44-45","Must remain lawful good and follow the paladin code; violating its conditions can cause loss of class abilities until atonement.",null],["ranger-weapon-armor-proficiency","Weapon and Armor Proficiency","47","Proficient with all simple and martial weapons, light armor, and shields except tower shields.",null],["ranger-favored-enemy","Favored Enemy","47","Choose favored enemy categories and gain scaling skill and weapon-damage bonuses against them.","other"],["ranger-track","Track","48","Gain Track as a bonus feat.","feat"],["ranger-wild-empathy","Wild Empathy","47","Influence animals with a check based on ranger level and Charisma modifier.",null],["ranger-combat-style","Combat Style","48","Choose archery or two-weapon combat and gain the style''s benefits while in light or no armor.","other"],["ranger-endurance","Endurance","48","Gain Endurance as a bonus feat.","feat"],["ranger-animal-companion","Animal Companion","48","Gain an animal companion with effective druid level equal to one-half ranger level.",null],["ranger-spells","Spells","48","Beginning at 4th level, prepare and cast divine ranger spells using Wisdom; caster level is one-half ranger level.",null],["ranger-improved-combat-style","Improved Combat Style","48","Gain the improved feat for the selected ranger combat style while eligible.",null],["ranger-woodland-stride","Woodland Stride","48","Move through natural undergrowth at normal speed without taking the usual impairment.",null],["ranger-swift-tracker","Swift Tracker","48","Track at normal speed with reduced penalties and at greater speed with the class-defined penalty.",null],["ranger-evasion","Evasion","48","On a successful Reflex save against a qualifying effect, take no damage while in light or no armor.",null],["ranger-combat-style-mastery","Combat Style Mastery","48","Gain the mastery feat for the selected combat style while eligible.",null],["ranger-camouflage","Camouflage","48","Use Hide in natural terrain even when the terrain does not grant cover or concealment.",null],["ranger-hide-in-plain-sight","Hide in Plain Sight","48","Use Hide in natural terrain even while being observed.",null],["rogue-weapon-armor-proficiency","Weapon and Armor Proficiency","50","Proficient with simple weapons plus hand crossbow, rapier, sap, shortbow, and short sword; proficient with light armor.",null],["rogue-sneak-attack","Sneak Attack","50","Deal extra precision damage when the target is denied Dexterity to Armor Class or is flanked, subject to range and creature restrictions.",null],["rogue-trapfinding","Trapfinding","50","Use Search to find difficult traps and Disable Device to disarm magic traps; may bypass a trap after exceeding its Disable Device DC sufficiently.",null],["rogue-evasion","Evasion","50","On a successful Reflex save against a qualifying effect, take no damage while in light or no armor.",null],["rogue-trap-sense","Trap Sense","50","Gain a scaling bonus on Reflex saves and Armor Class against traps.",null],["rogue-uncanny-dodge","Uncanny Dodge","50","Retain Dexterity bonus to Armor Class when flat-footed or attacked by an unseen foe, subject to the class feature''s restrictions.",null],["rogue-improved-uncanny-dodge","Improved Uncanny Dodge","50","Cannot be flanked except by a sufficiently higher-level rogue; compatible uncanny-dodge class levels stack as described.",null],["rogue-special-ability","Rogue Special Ability","50-51","Choose a rogue special ability from the available list, including crippling strike, defensive roll, improved evasion, opportunist, skill mastery, slippery mind, or a feat.","other"],["sorcerer-weapon-armor-proficiency","Weapon and Armor Proficiency","54","Proficient with all simple weapons; not proficient with armor or shields, and armor can interfere with arcane spells with somatic components.",null],["sorcerer-spells","Spells","54","Casts arcane sorcerer spells spontaneously using Charisma; spells known are limited by class level.",null],["sorcerer-summon-familiar","Familiar","54","May obtain a familiar whose abilities improve with the master''s applicable class levels.",null],["wizard-weapon-armor-proficiency","Weapon and Armor Proficiency","55-56","Proficient with club, dagger, heavy crossbow, light crossbow, and quarterstaff; not proficient with armor or shields, and armor can interfere with arcane spells with somatic components.",null],["wizard-spells","Spells","55-57","Prepares and casts arcane wizard spells from a spellbook using Intelligence.",null],["wizard-summon-familiar","Familiar","55-56","May obtain a familiar whose abilities improve with the master''s applicable class levels.",null],["wizard-scribe-scroll","Scribe Scroll","57","Gain Scribe Scroll as a bonus feat at 1st level.",null],["wizard-bonus-feat","Wizard Bonus Feat","57","At 5th level and every five wizard levels thereafter, gain a bonus metamagic, item creation, or Spell Mastery feat as allowed by the class feature.","feat"],["wizard-school-specialization","School Specialization","57","May specialize in a school of magic, gaining additional prepared spell capacity in that school while giving up access to prohibited schools.","school"]]')
)
INSERT OR IGNORE INTO dnd35_class_features
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,special_ability_id,choice_kind)
SELECT 'phb-class-feature-'||d.slug,s.id,d.source_page,d.slug,d.name,d.description,d.description,0,NULL,1,NULL,d.choice_kind
FROM desired d CROSS JOIN dnd35_sources s
WHERE s.slug='players-handbook-3-5' AND s.owner_user_id IS NULL;
